import json

class ImportProblem(Exception):
    def __init__(self, line):
        self.line = line
        super().__init__(f'invalid line {line}')

def _validate_line(line, raw):
    try:
        text = raw.decode('utf-8')
    except UnicodeDecodeError:
        raise ImportProblem(line) from None
    try:
        record = json.loads(text)
    except ValueError:
        raise ImportProblem(line) from None
    if not isinstance(record, dict):
        raise ImportProblem(line) from None
    record_id = record.get('id')
    if not isinstance(record_id, str) or record_id == '':
        raise ImportProblem(line) from None
    count = record.get('count')
    if isinstance(count, bool) or not isinstance(count, int):
        raise ImportProblem(line) from None
    return record

def import_bytes(payload, store):
    records = []
    for line, raw in enumerate(payload.splitlines(), 1):
        if not raw.strip():
            continue
        records.append(_validate_line(line, raw))
    for record in records:
        store.append(record)
    return len(records)

